mapper.select:
SELECT h.swap_id, h.hop_index, h.dex, h.pool, h.token_in, tin.symbol AS token_in_symbol, tin.decimals AS token_in_decimals, h.amount_in, h.token_out, tout.symbol AS token_out_symbol, tout.decimals AS token_out_decimals, h.amount_out, h.log_index FROM swap_hop h INNER JOIN swap sw ON sw.id = h.swap_id LEFT JOIN token tin ON tin.chain_id = sw.chain_id AND tin.address = h.token_in LEFT JOIN token tout ON tout.chain_id = sw.chain_id AND tout.address = h.token_out WHERE h.swap_id IN
#{id}
ORDER BY h.swap_id, h.hop_index
